package benchmark

import "strconv"

type ScoreError int

const (
	Malformed ScoreError = iota
	InvalidScore
	DuplicateName
)

type ScoreResult interface {
	isScoreResult()
}

type ParsedScores struct {
	Scores map[string]int64
}

type ScoreFailure struct {
	Line  int64
	Error ScoreError
}

func (ParsedScores) isScoreResult() {}
func (ScoreFailure) isScoreResult() {}

func ParseScores(lines []string) ScoreResult {
	scores := make(map[string]int64)

	for i, line := range lines {
		sep := -1
		for j := 0; j < len(line); j++ {
			if line[j] == '=' {
				if sep != -1 {
					return ScoreFailure{Line: int64(i), Error: Malformed}
				}
				sep = j
			}
		}

		if sep <= 0 {
			return ScoreFailure{Line: int64(i), Error: Malformed}
		}

		name := line[:sep]
		scoreText := line[sep+1:]

		value, err := strconv.ParseInt(scoreText, 10, 64)
		if err != nil || strconv.FormatInt(value, 10) != scoreText {
			return ScoreFailure{Line: int64(i), Error: InvalidScore}
		}

		if _, exists := scores[name]; exists {
			return ScoreFailure{Line: int64(i), Error: DuplicateName}
		}

		scores[name] = value
	}

	return ParsedScores{Scores: scores}
}

