#[derive(Debug, PartialEq, Eq)]
pub struct Interval {
    pub start: i64,
    pub end: i64,
}

pub fn merge_sorted_intervals(intervals: Vec<Interval>) -> Vec<Interval> {
    let mut iterator = intervals.into_iter();
    let mut merged = Vec::new();

    let first = match iterator.next() {
        Some(interval) => interval,
        None => return merged,
    };

    let mut current = Interval {
        start: first.start,
        end: first.end,
    };

    for next in iterator {
        if next.start <= current.end {
            if next.end > current.end {
                current.end = next.end;
            }
        } else {
            merged.push(Interval {
                start: current.start,
                end: current.end,
            });
            current = Interval {
                start: next.start,
                end: next.end,
            };
        }
    }

    merged.push(Interval {
        start: current.start,
        end: current.end,
    });

    merged
}

