type Accepted struct {
	State OrderState
}

func (Accepted) isTransitionResult() {}

type Rejected struct {
	Error TransitionError
}

func (Rejected) isTransitionResult() {}

func Transition(state OrderState, event OrderEvent) TransitionResult {
	var result TransitionResult

	switch state {
	case Draft:
		result = Rejected{Error: EventNotAllowed}
		switch event {
		case Submit:
			result = Accepted{State: Submitted}
		case Pay:
			result = Rejected{Error: EventNotAllowed}
		case Ship:
			result = Rejected{Error: EventNotAllowed}
		case Cancel:
			result = Accepted{State: Cancelled}
		}
	case Submitted:
		result = Rejected{Error: EventNotAllowed}
		switch event {
		case Submit:
			result = Rejected{Error: EventNotAllowed}
		case Pay:
			result = Accepted{State: Paid}
		case Ship:
			result = Rejected{Error: EventNotAllowed}
		case Cancel:
			result = Accepted{State: Cancelled}
		}
	case Paid:
		result = Rejected{Error: EventNotAllowed}
		switch event {
		case Submit:
			result = Rejected{Error: EventNotAllowed}
		case Pay:
			result = Rejected{Error: EventNotAllowed}
		case Ship:
			result = Accepted{State: Shipped}
		case Cancel:
			result = Accepted{State: Cancelled}
		}
	case Shipped:
		result = Rejected{Error: TerminalState}
		switch event {
		case Submit:
			result = Rejected{Error: TerminalState}
		case Pay:
			result = Rejected{Error: TerminalState}
