			result = Rejected{Error: TerminalState}
		case Pay:
			result = Rejected{Error: TerminalState}
		case Ship:
			result = Rejected{Error: TerminalState}
		case Cancel:
			result = Rejected{Error: TerminalState}
		}
	}

	return result
}

