def _parse_score(text: str) -> int | None:
    if text == "":
        return None

    negative: bool = text[0] == "-"
    digits: str = text[1:] if negative else text

    if digits == "":
        return None

    if digits[0] == "0":
        if digits != "0":
            return None
        if negative:
            return None
    elif digits[0] < "1" or digits[0] > "9":
        return None

    limit: int = 9_223_372_036_854_775_808 if negative else 9_223_372_036_854_775_807
    value: int = 0

    for character in digits:
        if character < "0" or character > "9":
            return None
        value = value * 10 + ord(character) - ord("0")
        if value > limit:
            return None

    if negative:
        return -value
    return value


def parse_scores(lines: list[str]) -> ScoreResult:
    scores: dict[str, int] = {}
    seen_names: set[str] = set()

    for line_number, line in enumerate(lines):
