package benchmark

type Expr interface{ isExpr() }

type Literal struct{ Value int64 }
type Add struct{ Left, Right Expr }
type Divide struct{ Numerator, Denominator Expr }
type Negate struct{ Inner Expr }

func (Literal) isExpr() {}
func (Add) isExpr()     {}
func (Divide) isExpr()  {}
func (Negate) isExpr()  {}

type EvalResult interface{ isEvalResult() }

type ValueResult struct{ Value int64 }
type DivisionByZero struct{}

func (ValueResult) isEvalResult()   {}
func (DivisionByZero) isEvalResult() {}

func Evaluate(expression Expr) EvalResult {
	var result EvalResult

	switch value := expression.(type) {
	case Literal:
		result = ValueResult{Value: value.Value}

	case Add:
		left := Evaluate(value.Left)
		switch leftValue := left.(type) {
		case ValueResult:
			right := Evaluate(value.Right)
			switch rightValue := right.(type) {
			case ValueResult:
				result = ValueResult{Value: leftValue.Value + rightValue.Value}
			case DivisionByZero:
				result = rightValue
			}
		case DivisionByZero:
			result = leftValue
		}

	case Divide:
		numerator := Evaluate(value.Numerator)
		switch numeratorValue := numerator.(type) {
		case ValueResult:
			denominator := Evaluate(value.Denominator)
			switch denominatorValue := denominator.(type) {
			case ValueResult:
				if denominatorValue.Value == 0 {
					result = DivisionByZero{}
				} else {
					result = ValueResult{Value: numeratorValue.Value / denominatorValue.Value}
				}
			case DivisionByZero:
				result = denominatorValue
			}
		case DivisionByZero:
			result = numeratorValue
		}

	case Negate:
		inner := Evaluate(value.Inner)
		switch innerValue := inner.(type) {
		case ValueResult:
			result = ValueResult{Value: -innerValue.Value}
		case DivisionByZero:
			result = innerValue
		}
	}

	return result
}

