#[derive(Debug, PartialEq, Eq)]
pub enum ScoreError {
    Malformed,
    InvalidScore,
    DuplicateName,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ScoreResult {
    Parsed(std::collections::BTreeMap<String, i64>),
    Failure { line: i64, error: ScoreError },
}

pub fn parse_scores(lines: Vec<String>) -> ScoreResult {
    let mut scores = std::collections::BTreeMap::new();

    for (index, line) in lines.iter().enumerate() {
        let parts = line.split_once('=');

        match parts {
            Some((name, score_text)) => {
                if name.is_empty() || score_text.contains('=') {
                    return ScoreResult::Failure {
                        line: index as i64,
                        error: ScoreError::Malformed,
                    };
                }

                match score_text.parse::<i64>() {
                    Ok(score) => {
                        if score.to_string() != score_text {
                            return ScoreResult::Failure {
                                line: index as i64,
                                error: ScoreError::InvalidScore,
                            };
                        }

                        if scores.contains_key(name) {
                            return ScoreResult::Failure {
                                line: index as i64,
                                error: ScoreError::DuplicateName,
                            };
                        }

                        scores.insert(name.to_owned(), score);
                    }
                    Err(error) => {
                        let _ = error;
                        return ScoreResult::Failure {
                            line: index as i64,
                            error: ScoreError::InvalidScore,
                        };
                    }
                }
            }
            None => {
                return ScoreResult::Failure {
                    line: index as i64,
                    error: ScoreError::Malformed,
                };
            }
        }
    }

    ScoreResult::Parsed(scores)
}

