export type InventoryEvent = { readonly kind: "stock"; readonly sku: string; readonly quantity: bigint } | { readonly kind: "sale"; readonly sku: string; readonly quantity: bigint };
export type InventoryResult = { readonly kind: "accepted"; readonly balances: ReadonlyMap<string, bigint> } | { readonly kind: "rejected"; readonly index: bigint; readonly sku: string };

export function applyInventory(events: readonly InventoryEvent[]): InventoryResult {
  const balances = new Map<string, bigint>();

  for (let i = 0; i < events.length; i++) {
    const event = events[i];

    switch (event.kind) {
      case "stock":
        if (event.quantity <= 0n) {
          return { kind: "rejected", index: BigInt(i), sku: event.sku };
        }

        balances.set(event.sku, (balances.get(event.sku) ?? 0n) + event.quantity);
        break;

      case "sale": {
        if (event.quantity <= 0n) {
          return { kind: "rejected", index: BigInt(i), sku: event.sku };
        }

        const current = balances.get(event.sku) ?? 0n;
        if (event.quantity > current) {
          return { kind: "rejected", index: BigInt(i), sku: event.sku };
        }

        balances.set(event.sku, current - event.quantity);
        break;
      }
    }
  }

  return { kind: "accepted", balances };
}

