package benchmark

type Expr interface{ isExpr() }

type Literal struct{ Value int64 }
type Add struct{ Left, Right Expr }
type Divide struct{ Numerator, Denominator Expr }
type Negate struct{ Inner Expr }

func (Literal) isExpr() {}
func (Add) isExpr() {}
func (Divide) isExpr() {}
func (Negate) isExpr() {}

type EvalResult interface{ isEvalResult() }

type ValueResult struct{ Value int64 }
type DivisionByZero struct{}

func (ValueResult) isEvalResult() {}
func (DivisionByZero) isEvalResult() {}

func Evaluate(expression Expr) (result EvalResult) {
	switch expression := expression.(type) {
	case Literal:
		result = ValueResult{Value: expression.Value}
	case Add:
		leftResult := Evaluate(expression.Left)
		switch leftResult := leftResult.(type) {
		case ValueResult:
			rightResult := Evaluate(expression.Right)
			switch rightResult := rightResult.(type) {
			case ValueResult:
				result = ValueResult{Value: leftResult.Value + rightResult.Value}
			case DivisionByZero:
				result = rightResult
			}
		case DivisionByZero:
			result = leftResult
		}
	case Divide:
		numeratorResult := Evaluate(expression.Numerator)
		switch numeratorResult := numeratorResult.(type) {
		case ValueResult:
			denominatorResult := Evaluate(expression.Denominator)
			switch denominatorResult := denominatorResult.(type) {
			case ValueResult:
				if denominatorResult.Value == 0 {
					result = DivisionByZero{}
				} else {
					result = ValueResult{Value: numeratorResult.Value / denominatorResult.Value}
				}
			case DivisionByZero:
				result = denominatorResult
			}
		case DivisionByZero:
			result = numeratorResult
		}
	case Negate:
		innerResult := Evaluate(expression.Inner)
		switch innerResult := innerResult.(type) {
		case ValueResult:
			result = ValueResult{Value: -innerResult.Value}
		case DivisionByZero:
			result = innerResult
		}
	}
	return result
}
