@dataclass(frozen=True)
class Literal:
    value: int

@dataclass(frozen=True)
class Add:
    left: Expr
    right: Expr

@dataclass(frozen=True)
class Divide:
    numerator: Expr
    denominator: Expr

@dataclass(frozen=True)
class Negate:
    inner: Expr

type Expr = Literal | Add | Divide | Negate

@dataclass(frozen=True)
class ValueResult:
    value: int

@dataclass(frozen=True)
class DivisionByZero:
    pass

type EvalResult = ValueResult | DivisionByZero


def evaluate(expression: Expr) -> EvalResult:
    match expression:
        case Literal(value):
            return ValueResult(value)

        case Add(left, right):
            left_result = evaluate(left)
            match left_result:
                case ValueResult(left_value):
                    right_result = evaluate(right)
                    match right_result:
                        case ValueResult(right_value):
                            return ValueResult(left_value + right_value)
                        case DivisionByZero():
                            return DivisionByZero()
                case DivisionByZero():
                    return DivisionByZero()

        case Divide(numerator, denominator):
            numerator_result = evaluate(numerator)
            match numerator_result:
                case ValueResult(numerator_value):
                    denominator_result = evaluate(denominator)
                    match denominator_result:
                        case ValueResult(denominator_value):
                            if denominator_value == 0:
                                return DivisionByZero()
                            quotient = abs(numerator_value) // abs(denominator_value)
                            if (numerator_value < 0) != (denominator_value < 0):
                                quotient = -quotient
                            return ValueResult(quotient)
                        case DivisionByZero():
                            return DivisionByZero()
                case DivisionByZero():
                    return DivisionByZero()

        case Negate(inner):
            inner_result = evaluate(inner)
            match inner_result:
                case ValueResult(value):
                    return ValueResult(-value)
                case DivisionByZero():
                    return DivisionByZero()

