class Accepted:
    balances: dict[str, int]


@dataclass(frozen=True)
class Rejected:
    index: int
    sku: str


type InventoryResult = Accepted | Rejected


def apply_inventory(events: list[InventoryEvent]) -> InventoryResult:
    balances: dict[str, int] = {}

    for index, event in enumerate(events):
        if isinstance(event, Stock):
            if event.quantity <= 0:
                return Rejected(index=index, sku=event.sku)
            balances[event.sku] = balances.get(event.sku, 0) + event.quantity
        elif isinstance(event, Sale):
            if event.quantity <= 0:
                return Rejected(index=index, sku=event.sku)
            current_balance: int = balances.get(event.sku, 0)
            if current_balance < event.quantity:
                return Rejected(index=index, sku=event.sku)
            balances[event.sku] = current_balance - event.quantity

    return Accepted(balances=balances)

