type Closed struct{}

func (Active) isAccountState() {}
func (Suspended) isAccountState() {}
func (Locked) isAccountState() {}
func (Closed) isAccountState() {}

func CanSignIn(state AccountState) bool {
	result := false
	switch state.(type) {
	case Active:
		result = true
	case Suspended:
		result = false
	case Locked:
		result = false
	case Closed:
		result = false
	}
