	switch state := state.(type) {
	case Active:
		result = "active"
	case Suspended:
		result = "suspended:" + state.Reason
	case Locked:
		result = "locked:" + strconv.FormatInt(state.FailedAttempts, 10)
	case Closed:
		result = "closed"
	}
	return result
}

