export type ScoreResult =
  | { readonly kind: "accepted"; readonly scores: ReadonlyMap<string, bigint> }
  | { readonly kind: "rejected"; readonly line: bigint; readonly error: ScoreError };

type ShapeResult =
  | { readonly kind: "valid"; readonly name: string; readonly scoreText: string }
  | { readonly kind: "malformed" };

type ScoreParseResult =
  | { readonly kind: "valid"; readonly score: bigint }
  | { readonly kind: "invalid_score" };

function parseShape(line: string): ShapeResult {
  const separator = line.indexOf("=");

  if (separator <= 0 || separator !== line.lastIndexOf("=") || separator === line.length - 1) {
    return { kind: "malformed" };
  }

  return {
    kind: "valid",
    name: line.slice(0, separator),
    scoreText: line.slice(separator + 1),
  };
}

function parseScore(text: string): ScoreParseResult {
  try {
    const score = BigInt(text);
    const minimum = -9223372036854775808n;
    const maximum = 9223372036854775807n;

    if (score < minimum || score > maximum || score.toString() !== text) {
      return { kind: "invalid_score" };
    }

    return { kind: "valid", score };
  } catch (error: unknown) {
    return { kind: "invalid_score" };
  }
}

export function parseScores(lines: readonly string[]): ScoreResult {
  const scores = new Map<string, bigint>();

  for (let index = 0; index < lines.length; index += 1) {
    const shape = parseShape(lines[index]);

    switch (shape.kind) {
      case "malformed":
        return { kind: "rejected", line: BigInt(index), error: "malformed" };
      case "valid": {
        const parsed = parseScore(shape.scoreText);

        switch (parsed.kind) {
          case "invalid_score":
            return { kind: "rejected", line: BigInt(index), error: "invalid_score" };
          case "valid":
            if (scores.has(shape.name)) {
              return { kind: "rejected", line: BigInt(index), error: "duplicate_name" };
            }

            scores.set(shape.name, parsed.score);
            break;
        }
        break;
      }
    }
  }

  return { kind: "accepted", scores };
}

