pub enum Expr {
    Literal(i64),
    Add(Box<Expr>, Box<Expr>),
    Divide(Box<Expr>, Box<Expr>),
    Negate(Box<Expr>),
}

#[derive(Debug, PartialEq, Eq)]
pub enum EvalResult {
    Value(i64),
    DivisionByZero,
}

pub fn evaluate(expression: Expr) -> EvalResult {
    match expression {
        Expr::Literal(value) => EvalResult::Value(value),
        Expr::Add(left, right) => match (evaluate(*left), evaluate(*right)) {
            (EvalResult::Value(left_value), EvalResult::Value(right_value)) => {
                EvalResult::Value(left_value + right_value)
            }
            (EvalResult::DivisionByZero, EvalResult::Value(_)) => EvalResult::DivisionByZero,
            (EvalResult::Value(_), EvalResult::DivisionByZero) => EvalResult::DivisionByZero,
            (EvalResult::DivisionByZero, EvalResult::DivisionByZero) => {
                EvalResult::DivisionByZero
            }
        },
        Expr::Divide(numerator, denominator) => match evaluate(*numerator) {
            EvalResult::DivisionByZero => EvalResult::DivisionByZero,
            EvalResult::Value(numerator_value) => match evaluate(*denominator) {
                EvalResult::DivisionByZero => EvalResult::DivisionByZero,
                EvalResult::Value(denominator_value) => {
                    if denominator_value == 0 {
                        EvalResult::DivisionByZero
                    } else {
                        EvalResult::Value(numerator_value / denominator_value)
                    }
                }
            },
        },
        Expr::Negate(child) => match evaluate(*child) {
            EvalResult::Value(value) => EvalResult::Value(-value),
            EvalResult::DivisionByZero => EvalResult::DivisionByZero,
        },
    }
}

