pub enum InventoryEvent {
    Stock { sku: String, quantity: i64 },
    Sale { sku: String, quantity: i64 },
}

#[derive(Debug, PartialEq, Eq)]
pub enum InventoryResult {
    Accepted(std::collections::BTreeMap<String, i64>),
    Rejected { index: i64, sku: String },
}

pub fn apply_inventory(events: Vec<InventoryEvent>) -> InventoryResult {
    let mut balances = std::collections::BTreeMap::new();

    for (index, event) in events.into_iter().enumerate() {
        let index = index as i64;

        match event {
            InventoryEvent::Stock { sku, quantity } => {
                if quantity <= 0 {
                    return InventoryResult::Rejected { index, sku };
                }

                match balances.entry(sku) {
                    std::collections::btree_map::Entry::Vacant(entry) => {
                        entry.insert(quantity);
                    }
                    std::collections::btree_map::Entry::Occupied(mut entry) => {
                        *entry.get_mut() += quantity;
                    }
                }
            }
            InventoryEvent::Sale { sku, quantity } => {
                if quantity <= 0 {
                    return InventoryResult::Rejected { index, sku };
                }

                match balances.get_mut(&sku) {
                    Some(balance) => {
                        if *balance < quantity {
                            return InventoryResult::Rejected { index, sku };
                        }

                        *balance -= quantity;
                    }
                    None => {
                        return InventoryResult::Rejected { index, sku };
                    }
                }
            }
        }
    }

    InventoryResult::Accepted(balances)
}

