namespace benchmark

enum InventoryEvent:
    stock(sku: string, quantity: int64)
    sale(sku: string, quantity: int64)

enum InventoryResult:
    accepted(balances: map[string, int64])
    rejected(index: int64, sku: string)

function apply_inventory(events: list[InventoryEvent]) returns InventoryResult:
    mutable map[string, int64] balances = map.new[string, int64]()
    int64 index = 0

    for event in events:
        match event:
            stock(sku, quantity):
                if quantity <= 0:
                    return InventoryResult.rejected(index, sku)
                int64 prior = map.get_or[string, int64](clone balances, sku, 0)
                balances = map.set[string, int64](balances, sku, prior + quantity)

            sale(sku, quantity):
                if quantity <= 0:
                    return InventoryResult.rejected(index, sku)
                int64 available = map.get_or[string, int64](clone balances, sku, 0)
                if quantity > available:
                    return InventoryResult.rejected(index, sku)
                balances = map.set[string, int64](balances, sku, available - quantity)

        index = index + 1

    return InventoryResult.accepted(balances)

