    Parsed(std::collections::BTreeMap<String, i64>),
    Failure { line: i64, error: ScoreError },
}

pub fn parse_scores(lines: Vec<String>) -> ScoreResult {
    let mut scores = std::collections::BTreeMap::new();

    for (index, line) in lines.into_iter().enumerate() {
        let mut parts = line.split('=');

        let shape = match (parts.next(), parts.next(), parts.next()) {
            (Some(name), Some(score), None) => Some((name, score)),
            (Some(_), Some(_), Some(_)) => None,
            (Some(_), None, Some(_)) => None,
            (Some(_), None, None) => None,
            (None, Some(_), Some(_)) => None,
            (None, Some(_), None) => None,
            (None, None, Some(_)) => None,
            (None, None, None) => None,
        };

        let (name, score_text) = match shape {
            Some(values) => values,
            None => {
                return ScoreResult::Failure {
                    line: index as i64,
                    error: ScoreError::Malformed,
                };
            }
        };

        if name.is_empty() {
            return ScoreResult::Failure {
                line: index as i64,
                error: ScoreError::Malformed,
            };
        }

        let score = match score_text.parse::<i64>() {
            Ok(value) => value,
            Err(parse_error) => {
                let _ = parse_error;
                return ScoreResult::Failure {
                    line: index as i64,
                    error: ScoreError::InvalidScore,
                };
            }
        };

        if score_text != score.to_string() {
            return ScoreResult::Failure {
                line: index as i64,
                error: ScoreError::InvalidScore,
            };
        }

        match scores.entry(name.to_owned()) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(score);
            }
            std::collections::btree_map::Entry::Occupied(entry) => {
                let _ = entry;
                return ScoreResult::Failure {
                    line: index as i64,
                    error: ScoreError::DuplicateName,
                };
            }
        }
    }

    ScoreResult::Parsed(scores)
}

