from dataclasses import dataclass
from enum import Enum

class ScoreError(Enum):
    MALFORMED = "malformed"
    INVALID_SCORE = "invalid_score"
    DUPLICATE_NAME = "duplicate_name"

@dataclass(frozen=True)
class ParsedScores:
    scores: dict[str, int]

@dataclass(frozen=True)
class ScoreFailure:
    line: int
    error: ScoreError

type ScoreResult = ParsedScores | ScoreFailure

def parse_scores(lines: list[str]) -> ScoreResult:
    scores: dict[str, int] = {}

    for line_number, line in enumerate(lines):
        parts = line.split("=")
        if len(parts) != 2 or parts[0] == "":
            return ScoreFailure(line_number, ScoreError.MALFORMED)

        name, text = parts
        valid = False
        magnitude = text

        if text == "0":
            valid = True
        elif text.startswith("-"):
            magnitude = text[1:]
            if (
                magnitude != ""
                and magnitude[0] != "0"
                and all("0" <= char <= "9" for char in magnitude)
                and (
                    len(magnitude) < 19
                    or (
                        len(magnitude) == 19
                        and magnitude <= "9223372036854775808"
                    )
                )
            ):
                valid = True
        elif (
            text[0] != "0"
            and all("0" <= char <= "9" for char in text)
            and (
                len(text) < 19
                or (
                    len(text) == 19
                    and text <= "9223372036854775807"
                )
            )
        ):
            valid = True

        if not valid:
            return ScoreFailure(line_number, ScoreError.INVALID_SCORE)

        value = int(text)
        if name in scores:
            return ScoreFailure(line_number, ScoreError.DUPLICATE_NAME)

        scores[name] = value

    return ParsedScores(scores)

