export type ScoreError = "malformed" | "invalid_score" | "duplicate_name";

export type ScoreResult =
  | { readonly kind: "accepted"; readonly scores: ReadonlyMap<string, bigint> }
  | {
      readonly kind: "rejected";
      readonly line: bigint;
      readonly error: ScoreError;
    };

export function parseScores(lines: readonly string[]): ScoreResult {
  const scores = new Map<string, bigint>();
  const minInt64 = -9223372036854775808n;
  const maxInt64 = 9223372036854775807n;

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const equals = line.indexOf("=");

    if (equals <= 0 || equals !== line.lastIndexOf("=")) {
      return { kind: "rejected", line: BigInt(index), error: "malformed" };
    }

    const name = line.slice(0, equals);
    const scoreText = line.slice(equals + 1);

    if (
      !/^(0|-?[1-9][0-9]*)$/.test(scoreText)
    ) {
      return {
        kind: "rejected",
        line: BigInt(index),
        error: "invalid_score",
      };
    }

    const score = BigInt(scoreText);

    if (
      score < minInt64 ||
      score > maxInt64 ||
      score.toString() !== scoreText
    ) {
      return {
        kind: "rejected",
        line: BigInt(index),
        error: "invalid_score",
      };
    }

    if (scores.has(name)) {
      return {
        kind: "rejected",
        line: BigInt(index),
        error: "duplicate_name",
      };
    }

    scores.set(name, score);
  }

  return { kind: "accepted", scores };
}

