import "strconv"

type AccountState interface{ isAccountState() }

type Active struct{}
type Suspended struct{ Reason string }
type Locked struct{ FailedAttempts int64 }
type Closed struct{}

func (Active) isAccountState()    {}
func (Suspended) isAccountState() {}
func (Locked) isAccountState()    {}
func (Closed) isAccountState()    {}

func CanSignIn(state AccountState) (result bool) {
	switch state.(type) {
	case Active:
		result = true
	case Suspended:
		result = false
	case Locked:
		result = false
	case Closed:
		result = false
	}
	return
}

func StatusLabel(state AccountState) (result string) {
	result = "closed"
	switch state := state.(type) {
	case Active:
		result = "active"
	case Suspended:
		result = "suspended:" + state.Reason
	case Locked:
		result = "locked:" + strconv.FormatInt(state.FailedAttempts, 10)
	case Closed:
		result = "closed"
	}
	return
}

func Suspend(state AccountState, reason string) (result AccountState) {
	switch state := state.(type) {
	case Active:
		result = Suspended{Reason: reason}
	case Suspended:
		result = state
	case Locked:
		result = state
	case Closed:
		result = state
	}
	return
}

