        (OrderState.CANCELLED, OrderEvent.PAY): Rejected(
            TransitionError.TERMINAL_STATE
        ),
        (OrderState.CANCELLED, OrderEvent.SHIP): Rejected(
            TransitionError.TERMINAL_STATE
        ),
        (OrderState.CANCELLED, OrderEvent.CANCEL): Rejected(
            TransitionError.TERMINAL_STATE
        ),
    }
    return transitions[(state, event)]
