#[derive(Debug, PartialEq, Eq)]
pub enum EvalResult {
    Value(i64),
    DivisionByZero,
}

pub fn evaluate(expression: Expr) -> EvalResult {
    match expression {
        Expr::Literal(value) => EvalResult::Value(value),
        Expr::Add(left, right) => match (evaluate(*left), evaluate(*right)) {
            (EvalResult::Value(left_value), EvalResult::Value(right_value)) => {
                EvalResult::Value(left_value + right_value)
            }
            (EvalResult::Value(_), EvalResult::DivisionByZero) => {
                EvalResult::DivisionByZero
            }
            (EvalResult::DivisionByZero, EvalResult::Value(_)) => {
                EvalResult::DivisionByZero
            }
            (EvalResult::DivisionByZero, EvalResult::DivisionByZero) => {
                EvalResult::DivisionByZero
            }
        },
        Expr::Divide(numerator, denominator) => {
            match (evaluate(*numerator), evaluate(*denominator)) {
                (EvalResult::Value(numerator_value), EvalResult::Value(denominator_value)) => {
                    if denominator_value == 0 {
                        EvalResult::DivisionByZero
                    } else {
                        EvalResult::Value(numerator_value / denominator_value)
                    }
                }
                (EvalResult::Value(_), EvalResult::DivisionByZero) => {
                    EvalResult::DivisionByZero
