def signed_gcd(a: int, b: int) -> int:
    a = abs(a)
    b = abs(b)
    while b:
        a, b = b, a % b
    return a

namespace benchmark

enum InventoryEvent:
    stock(sku: string, quantity: int64)
    sale(sku: string, quantity: int64)

enum InventoryResult:
    accepted(balances: map[string, int64])
    rejected(index: int64, sku: string)

function apply_inventory(events: list[InventoryEvent]) returns InventoryResult:
    let balances: map[string, int64] = {}
    let index: int64 = 0

    for event in events:
        match event:
            InventoryEvent.stock(sku, quantity):
                if quantity <= 0:
                    return InventoryResult.rejected(index, sku)
                balances[sku] = balances.get(sku, 0) + quantity

            InventoryEvent.sale(sku, quantity):
                if quantity <= 0:
                    return InventoryResult.rejected(index, sku)
                let balance: int64 = balances.get(sku, 0)
                if balance < quantity:
                    return InventoryResult.rejected(index, sku)
                balances[sku] = balance - quantity

        index = index + 1

    return InventoryResult.accepted(balances)

